# Surah Al-An'am (chapter 6) — part 12: ayat 114-123 (IDs 903-912)
SURAH = 6

ENTRIES = {
903: (
"کیا میں اللہ کے سوا — کوئی اور — فیصلہ کرنے والا — تلاش کروں — حالانکہ اس نے آپ پر — کتاب — تفصیل سے نازل کی ہے — اور — جن لوگوں کو ہم نے کتاب دی — وہ — جانتے ہیں — کہ وہ آپ کے رب کی طرف سے حق — کے ساتھ — نازل کی گئی — پس آپ — شک کرنے والوں میں سے نہ بنیں",
"""۱۔ اللہ کے سوا — کوئی اور — فیصلہ کرنے والا — نہیں۔
۲۔ ’’أَفَغَيْرَ اللّٰہِ أَبْتَغِي حَكَمًا وَهُوَ الَّذِي أَنزَلَ إِلَيْكُمُ الْكِتَابَ مُفَصَّلًا‘‘ — کیا میں اللہ کے سوا — کوئی اور — فیصلہ کرنے والا — تلاش کروں — حالانکہ اس نے آپ پر — کتاب — تفصیل سے نازل کی ہے — یعنی اللہ کا دیا ہوا فیصلہ — کامل — کتاب — میں — موجود ہے۔
۳۔ ’’وَالَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْلَمُونَ أَنَّهُ مُنَزَّلٌ مِّن رَّبِّكَ بِالْحَقِّ فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ‘‘ — اور — جن لوگوں کو ہم نے کتاب دی — وہ — جانتے ہیں — کہ وہ آپ کے رب کی طرف سے حق — کے ساتھ — نازل کی گئی — پس آپ — شک کرنے والوں میں سے نہ بنیں — یعنی اہلِ کتاب بھی جانتے ہیں کہ قرآن حق ہے۔
۴۔ عملی سبق: اللہ کے فیصلے پر — یقین — رکھو؛ شک سے بچو۔"""
),
904: (
"اور آپ کے رب کی — بات — پوری ہو گئی — سچائی اور انصاف — میں — اس کے کلمات کا کوئی بدل نہیں — اور وہ سننے والا — جاننے والا ہے",
"""۱۔ اللہ کا جملہ — سچ اور انصاف — میں پورا۔
۲۔ ’’وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَاتِهِ وَهُوَ السَّمِيعُ الْعَلِيمُ‘‘ — اور آپ کے رب کی — بات — پوری ہو گئی — سچائی اور انصاف — میں — اس کے کلمات کا کوئی بدل نہیں — اور وہ سننے والا — جاننے والا ہے — یعنی اللہ کی بات — سچ اور انصاف — دونوں میں مکمل — اور — غیر قابل تغیر ہے۔
۳۔ عملی سبق: اللہ کے — مکمل — فیصلے پر — یقین — رکھو؛ اللہ کی بات — نہ بدلے — گی۔"""
),
905: (
"اور اگر آپ — زمین پر — زیادہ تر لوگوں کی اطاعت کریں تو وہ — آپ کو — اللہ کے راستے سے — گمراہ کریں گے — وہ — صرف — گمان — کی — پیروی کرتے ہیں — اور وہ صرف اندازہ کر رہے ہیں",
"""۱۔ کثرتِ رائے — حق کی ضمانت نہیں۔
۲۔ ’’وَإِن تُطِعْ أَكْثَرَ مَن فِي الْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ اللّٰہِ‘‘ — اور اگر آپ — زمین پر — زیادہ تر لوگوں کی اطاعت کریں تو وہ — آپ کو — اللہ کے راستے سے — گمراہ کریں گے — یعنی — کثیر — لوگوں کی خواہش — حق نہیں — ہوتی۔
۳۔ ’’إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ‘‘ — وہ — صرف — گمان — کی — پیروی کرتے ہیں — اور وہ صرف اندازہ کر رہے ہیں — یعنی — لوگوں کی رائے — اندازہ — ہے — یقین نہیں۔
۴۔ عملی سبق: بھیڑ — کی پشت پر — چلنے کی جگہ — اللہ کے راستے پر — چلنا ضروری ہے۔"""
),
906: (
"بے شک تمہارا رب — وہی — ہے — سب سے زیادہ جاننے والا — کہ — کون — — اپنے راستے سے — گمراہ ہوتا ہے — اور وہی — سب سے زیادہ جاننے والا ہے — ہدایت یافتہ لوگوں کا",
"""۱۔ اللہ — گمراہوں کو — سب سے زیادہ جانتا ہے۔
۲۔ ’’إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ‘‘ — بے شک تمہارا رب — وہی — ہے — سب سے زیادہ جاننے والا — کہ — کون — — اپنے راستے سے — گمراہ ہوتا ہے — اور وہی — سب سے زیادہ جاننے والا ہے — ہدایت یافتہ لوگوں کا — یعنی اللہ — گمراہوں اور ہدایت یافتہ دونوں — کو — سب سے بہتر جانتا ہے۔
۳۔ عملی سبق: اللہ کے علم پر بھروسہ کرو؛ ہدایت — اللہ سے مانگو۔"""
),
907: (
"پس کھاؤ اس میں سے جس پر اللہ کا نام — ذبح کے وقت — لیا گیا ہو — اگر تم — اس — کی — آیات — پر — ایمان رکھتے ہو",
"""۱۔ اللہ کے نام پر ذبح — اللہ کا حکم۔
۲۔ ’’فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللّٰہِ عَلَيْهِ إِن كُنتُم بِآيَاتِهِ مُؤْمِنِينَ‘‘ — پس کھاؤ اس میں سے جس پر اللہ کا نام — ذبح کے وقت — لیا گیا ہو — اگر تم — اس — کی — آیات — پر — ایمان رکھتے ہو — یعنی اللہ پر ذبح — حرام نہیں — اسی کی — طرف — ایمان — ہے۔
۳۔ عملی سبق: اللہ کے نام پر ذبح کی ہوئی چیز — کھاؤ؛ ایمان کی تقاضا۔"""
),
908: (
"اور — تمہیں — کیا ہوا کہ — اس — میں سے نہیں کھاتے جس پر اللہ کا نام لیا گیا — حالانکہ — اس نے — تمہیں — حرام کردہ چیزیں — تفصیل سے بتا دی ہیں — سوائے اس کے — تم — بےبس ہو — اور — بہت سے لوگ — اپنی — خواہشات — سے — بغیر علم کے — گمراہ کرتے ہیں — بے شک تمہارا رب — حد سے بڑھنے والوں — کو — سب سے زیادہ جانتا ہے",
"""۱۔ اللہ — سب — حرام کردہ چیزیں — تفصیل سے بتا دی ہیں۔
۲۔ ’’وَمَا لَكُمْ أَلَّا تَأْكُلُوا مِمَّا ذُكِرَ اسْمُ اللّٰہِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ‘‘ — اور — تمہیں — کیا ہوا کہ — اس — میں سے نہیں کھاتے جس پر اللہ کا نام لیا گیا — حالانکہ — اس نے — تمہیں — حرام کردہ چیزیں — تفصیل سے بتا دی ہیں — سوائے اس کے — تم — بےبس ہو — یعنی اللہ نے — تفصیل سے — حرام چیزیں — بتادی ہیں — فراموشی کا — بہانہ — نہیں۔
۳۔ ’’وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَائِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِالْمُعْتَدِينَ‘‘ — اور — بہت سے لوگ — اپنی — خواہشات — سے — بغیر علم کے — گمراہ کرتے ہیں — بے شک تمہارا رب — حد سے بڑھنے والوں — کو — سب سے زیادہ جانتا ہے — یعنی خواہشات — گمراہی — کی — وجہ — ہیں۔
۴۔ عملی سبق: اللہ کے حرام کردہ — اشیاء سے بچو؛ خواہشات — تسلسل سے — پرہیز کرو۔"""
),
909: (
"اور — چھوڑ دو — ظاہری — اور باطنی — گناہ — کو — بے شک — وہ لوگ جو گناہ کماتے ہیں — عنقریب — ان — کو — بدلہ دیا جائے گا — اس — کے مطابق جو وہ کماتے ہیں",
"""۱۔ ظاہری اور باطنی — ہر — گناہ — ترک کرو۔
۲۔ ’’وَذَرُوا ظَاهِرَ الْإِثْمِ وَبَاطِنَهُ‘‘ — اور — چھوڑ دو — ظاہری — اور باطنی — گناہ — کو — یعنی غلطی — نہ صرف — ظاہر — بلکہ — دل کے — گناہ — بھی ترک کرو۔
۳۔ ’’إِنَّ الَّذِينَ يَكْسِبُونَ الْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا يَقْتَرِفُونَ‘‘ — بے شک — وہ لوگ جو گناہ کماتے ہیں — عنقریب — ان — کو — بدلہ دیا جائے گا — اس — کے مطابق جو وہ کماتے ہیں — یعنی گناہ کا بدلہ — اسی کے مطابق ہوگا۔
۴۔ عملی سبق: ظاہری اور باطنی — گناہوں — سے — بچو؛ اللہ کا خوف رکھو۔"""
),
910: (
"اور — تم — اس — میں سے مت کھاؤ — جس — پر — اللہ کا نام نہیں لیا گیا — حالانکہ — اس — میں — فسق — ہے — اور — بے شک — شیاطین — اپنے — دوستوں — کو — وحی کرتے ہیں — کہ — وہ تم سے — مجادلہ کریں — اور اگر — تم — ان — کی — اطاعت کرو گے — تو — تم — ضرور — مشرک ہو جاؤ گے",
"""۱۔ جس پر اللہ کا نام ذبح کے وقت نہ لیا گیا — نہ کھاؤ۔
۲۔ ’’وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللّٰہِ عَلَيْهِ وَإِنَّهُ لَفِسْقٌ‘‘ — اور — تم — اس — میں سے مت کھاؤ — جس — پر — اللہ کا نام نہیں لیا گیا — حالانکہ — اس — میں — فسق — ہے — یعنی بغیر اللہ کے نام کے — ذبیحہ — فسق — ہے۔
۳۔ ’’وَإِنَّ الشَّيَاطِينَ لَيُوحُونَ إِلَىٰ أَوْلِيَائِهِمْ لِيُجَادِلُوكُمْ‘‘ — اور — بے شک — شیاطین — اپنے — دوستوں — کو — وحی کرتے ہیں — کہ — وہ تم سے — مجادلہ کریں — یعنی شیاطین — اپنے دوستوں کو — بحث کے لیے بھیجتے ہیں۔
۴۔ ’’وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ‘‘ — اور اگر — تم — ان — کی — اطاعت کرو گے — تو — تم — ضرور — مشرک ہو جاؤ گے — یعنی بغیر اللہ کے نام کے ذبیحہ — شرک — ہے۔
۵۔ عملی سبق: اللہ کے بغیر — ذبیحہ — نہ کھاؤ؛ شیاطین کی بحث میں مت پڑو۔"""
),
911: (
"اور — کیا — وہ — جو — مردہ — تھا — پھر — ہم نے — اس — کو — زندہ کیا — اور — اس — کے لیے — ایک نور — بنایا — جو — اس کے ساتھ — لوگوں میں — چلتا ہے — اس کی طرح — ہے — جو — اندھیریوں میں — ہے — اس — سے — نکلنے — والا — نہیں — اسی طرح — کافروں کے لیے — ان کے — اعمال — مزین — کر دیے گئے ہیں",
"""۱۔ ایمان — مردہ کو زندہ کرنے جیسا ہے۔
۲۔ ’’أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ فِي النَّاسِ كَمَن مَّثَلُهُ فِي الظُّلُمَاتِ لَيْسَ بِخَارِجٍ مِّنْهَا‘‘ — اور — کیا — وہ — جو — مردہ — تھا — پھر — ہم نے — اس — کو — زندہ کیا — اور — اس — کے لیے — ایک نور — بنایا — جو — اس کے ساتھ — لوگوں میں — چلتا ہے — اس کی طرح — ہے — جو — اندھیریوں میں — ہے — اس — سے — نکلنے — والا — نہیں — یعنی ایمان — روح — کی زندگی — ہے۔
۳۔ ’’كَذَٰلِكَ زُيِّنَ لِلْكَافِرِينَ مَا كَانُوا يَعْمَلُونَ‘‘ — اسی طرح — کافروں کے لیے — ان کے — اعمال — مزین — کر دیے گئے ہیں — یعنی شیطان — کافروں کے اعمال — کو خوبصورتی دیتا ہے۔
۴۔ عملی سبق: اللہ کا دیا ہوا — نور — اپناؤ؛ ایمان — کی — روشنی — زندگی بناؤ۔"""
),
912: (
"اور اسی طرح ہم نے — ہر بستی — میں — بڑے مجرموں — کو — مقرر کیا — تاکہ — وہ — اس — میں — دھوکہ — دینے — کی — چال چلیں — اور — وہ — صرف — اپنے — نفسوں — کو دھوکہ دیتے ہیں — اور — انہیں — شعور — نہیں — ہوتا",
"""۱۔ ہر بستی میں — بڑے مجرم — دھوکہ دیتے ہیں۔
۲۔ ’’وَكَذَٰلِكَ جَعَلْنَا فِي كُلِّ قَرْيَۃٍ أَكَابِرَ مُجْرِمِيهَا لِيَمْكُرُوا فِيهَا‘‘ — اور اسی طرح ہم نے — ہر بستی — میں — بڑے مجرموں — کو — مقرر کیا — تاکہ — وہ — اس — میں — دھوکہ — دینے — کی — چال چلیں — یعنی ہر — بستی — میں بڑے مجرم — چال چلتا — ہیں۔
۳۔ ’’وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ‘‘ — اور — وہ — صرف — اپنے — نفسوں — کو دھوکہ دیتے ہیں — اور — انہیں — شعور — نہیں — ہوتا — یعنی — مجرم — سب سے پہلے — اپنا — نقصان کرتے ہیں۔
۴۔ عملی سبق: بڑے مجرموں کی — چال — سے بچو؛ اللہ کا خوف کرو۔"""
),
}
